/// An account (group of devices) as shown in the chat UI.
#[derive(Serialize)]
pub struct AccountInfo {
    pub account_id: String,
    pub device_count: usize,
    pub names: Vec<String>,
}

#[tauri::command]
pub async fn list_accounts(
    app: tauri::State<'_, crate::state::AppState>,
    policy: tauri::State<'_, crate::contact_policy::HiddenContactsState>,
    state: tauri::State<'_, NodeState>,
) -> Result<Vec<AccountInfo>, CommandError> {
    let admission = RuntimeAdmission::capture_current(&app, &state)?;
    let lease = admission.lease().clone();
    let owner = lease.owner().to_owned();
    let node = state.inner().clone();
    #[cfg(test)]
    let captured = app.owner_command_captured.clone();
    let app = app.inner().clone();
    let policy = policy.inner().clone();
    tokio::task::spawn_blocking(move || {
        // Runtime first, matching startup and runtime admission. Never wait for
        // it while holding the session needed by an installation or producer.
        #[cfg(test)]
        if let Some(entered) = captured.lock().unwrap().as_ref() {
            let _ = entered.send("contact-runtime-wait");
        }
        let guard = node.0.blocking_read();
        policy.transaction_for_lease(&app, &lease, || {
            node.check_installation(&lease)
                .map_err(|error| error.to_string())?;
            // Capture fresh presence inside the policy transaction so an older
            // poll cannot undo a later contact deletion.
            let rt = guard.as_ref().ok_or("Node not started")?;
            if rt.host_account_id() != Some(owner.as_str()) {
                return Err("Contact roster requires this account's running node".into());
            }
            let mut peers = rt.peers();
            peers.sort_by_key(|peer| std::cmp::Reverse(peer.last_seen));
            let live = peers
                .into_iter()
                .filter_map(|p| p.account_id.map(|id| (id, p.name, p.post_office)))
                .collect();
            let mut rows =
                merge_account_rows(live, rt.known_account_ids().map_err(|e| e.to_string())?);
            fill_account_names(
                &mut rows,
                rt.known_account_names()
                    .map_err(|error| error.to_string())?,
            );
            let personal = policy.personal_snapshot(&owner, &rt.handle())?;
            rows.retain(|row| !personal.deleted.contains(&row.account_id));
            Ok(rows)
        })
    })
    .await
    .map_err(|_| CommandError::Internal("Contact policy task failed".into()))?
    .map_err(CommandError::from)
}

#[cfg(test)]
pub(crate) fn online_account_ids(
    peers: Vec<mesh_talk_core::discovery::roster::PeerRecord>,
) -> Vec<String> {
    let now = std::time::Instant::now();
    peers
        .into_iter()
        .filter(|p| !p.post_office && !p.presence_evidence(now).is_empty())
        .filter_map(|p| p.account_id)
        .collect()
}

fn merge_account_rows(live: Vec<(String, String, bool)>, known: Vec<String>) -> Vec<AccountInfo> {
    use std::collections::BTreeMap;
    let mut by_account: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for account_id in known {
        // A durable conversation remains a contact even if its only device currently
        // discovered is a relay. Live relay discovery alone never creates a row.
        by_account.entry(account_id).or_default();
    }
    for (account_id, name, post_office) in live {
        if !post_office {
            by_account.entry(account_id).or_default().push(name);
        }
    }
    by_account
        .into_iter()
        .map(|(account_id, names)| AccountInfo {
            device_count: names.len(),
            names,
            account_id,
        })
        .collect()
}

fn fill_account_names(
    rows: &mut [AccountInfo],
    known: std::collections::HashMap<String, Vec<String>>,
) {
    for row in rows {
        if let Some(names) = known.get(&row.account_id).filter(|names| !names.is_empty()) {
            row.names = names.clone();
        }
    }
}

#[cfg(test)]
mod recovery_accounts_tests {
    use super::{fill_account_names, merge_account_rows};

    #[test]
    fn deletion_presence_uses_the_same_source_evidence_as_ui() {
        use mesh_talk_core::{
            discovery::roster::{PeerEndpoint, PeerRecord, RouteSource},
            identity::device::DeviceIdentity,
        };
        use std::time::{Duration, Instant};
        let now = Instant::now();
        let fresh = PeerRecord {
            public: DeviceIdentity::generate().public(),
            addr: "127.0.0.1:1234".parse().unwrap(),
            routes: vec![PeerEndpoint {
                addr: "127.0.0.1:1234".parse().unwrap(),
                source: RouteSource::Lan,
                last_seen: now,
                last_authenticated: None,
                presence_expires_at: None,
                presence_origin_expires_at: None,
                display_name: runtime.display_name(),
                history_revision: runtime.account_history_revision(),
                supports_push_state: true,
                supports_bounded_delivery: runtime.handle().bounded_delivery(),
                runtime_id: node.installed_runtime_id(admission.lease())?,
            })
        })
        .await
}

#[derive(Serialize)]
pub struct RosterObservation {
    identity: NodeIdentity,
    peers: Vec<crate::chat_commands::PeerInfo>,
    people: std::collections::HashMap<String, crate::chat_commands::PresenceInfo>,
}

/// One authorized discovery read; group metadata and bodies have separate owners.
#[tauri::command]
pub async fn owner_roster_observation(
    owner: String,
    app: tauri::State<'_, AppState>,
    node: tauri::State<'_, NodeState>,
) -> Result<RosterObservation, CommandError> {
    let admission = RuntimeAdmission::capture(&app, &node, &owner)?;
    roster_observation_with_snapshot(&admission, &node, owner, |handle| async move {
        handle.cached_peer_snapshot_async().await
    })
    .await
}

async fn roster_observation_with_snapshot<F, Fut>(
    admission: &RuntimeAdmission,
    node: &NodeState,
    owner: String,
    snapshot: F,
) -> Result<RosterObservation, CommandError>
where
    F: FnOnce(std::sync::Arc<mesh_talk_core::node::Node>) -> Fut,
    Fut: std::future::Future<
            Output = std::io::Result<Vec<mesh_talk_core::discovery::roster::PeerRecord>>,
        >,
{
    let handle = admission
        .with_runtime(|runtime| {
            if !runtime.discovery_available() {
                return Err(CommandError::Internal("discovery unavailable".into()));
            }
            Ok(runtime.handle())
        })
        .await?;
    let peers = snapshot(handle.clone()).await;
    admission
        .with_runtime(|runtime| {
            if !runtime.discovery_available() || !std::sync::Arc::ptr_eq(&runtime.handle(), &handle)
            {
                return Err(CommandError::not_started());
            }
            let peers = peers.map_err(|error| CommandError::Io(error.to_string()))?;
            let people = crate::chat_commands::project_people(runtime, &peers);
            Ok(RosterObservation {
                identity: NodeIdentity {
                    owner,
                    device_id: runtime.user_id().into(),
                    account_id: runtime.account_id().into(),
                    display_name: runtime.display_name(),
                    history_revision: runtime.account_history_revision(),
                    supports_push_state: true,
                    supports_bounded_delivery: runtime.handle().bounded_delivery(),
                    runtime_id: node.installed_runtime_id(admission.lease())?,
                },
                peers: peers
                    .into_iter()
                    .map(crate::chat_commands::PeerInfo::from)
                    .collect(),
                people,
            })
        })
        .await
}

#[derive(Serialize)]
#[serde(untagged)]
pub enum ConditionalPresence {
    Unchanged { unchanged: bool },
    Full(crate::chat_commands::PresenceResponse),
}

#[tauri::command]
pub async fn owner_presence_if_groups_changed(
    owner: String,
    known_group_revision: String,
    app: tauri::State<'_, AppState>,
    node: tauri::State<'_, NodeState>,
) -> Result<ConditionalPresence, CommandError> {
    let admission = RuntimeAdmission::capture(&app, &node, &owner)?;
    presence_if_groups_changed(&admission, &known_group_revision, || {
        crate::chat_commands::get_presence_for_state(&node, Some(String::new()))
    })
    .await
}

async fn presence_if_groups_changed<F, Fut>(
    admission: &RuntimeAdmission,
    known_group_revision: &str,
    refresh: F,
) -> Result<ConditionalPresence, CommandError>
where
    F: FnOnce() -> Fut,
    Fut: std::future::Future<Output = Result<crate::chat_commands::PresenceResponse, CommandError>>,
{
    presence_if_groups_changed_with_revision(
        admission,
        known_group_revision,
        |node, work| group_revision_with_work(node, work, |node| node.group_projection_revision()),
        refresh,
    )
    .await
}

async fn group_revision_with_work(
    node: std::sync::Arc<mesh_talk_core::node::Node>,
    work: mesh_talk_core::node::ParticipantWork,
    read: impl FnOnce(
        std::sync::Arc<mesh_talk_core::node::Node>,
    ) -> Result<[u8; 32], mesh_talk_core::eventlog::LogError>
    + Send
    + 'static,
) -> Result<String, CommandError> {
    let mut tasks = tokio::task::JoinSet::new();
    if !work.spawn(&mut tasks, move || read(node)) {
          user: state.user
            ? { ...state.user, display_name: identity.display_name! }
            : null,
        }));
    }
    if (!publishedAccountRoster?.current()) publishedAccountRoster = null;
    // Keep full reads concurrent. Heartbeats first inspect cheap discovery facts;
    // route-only changes still publish peers without rereading account history/policy.
    const observedPeers = presenceOnly
      ? ticket
        ? await ticket.read(lease.owner!).then(({ value }) => {
            if (
              value.identity.owner !== lease.owner ||
              value.identity.account_id !== identity.account_id ||
              value.identity.device_id !== identity.device_id ||
              value.identity.runtime_id !== identity.runtime_id
            )
              throw new Error("Roster source identity changed");
            return value.peers;
          })
        : await readWithDeadline(() => chat.listPeers())
      : null;
    if (!lease.current() || get().rosterRequest !== request || hasPending())
      return;
    const reuseAccounts =
      presenceOnly &&
      publishedAccountRoster?.current() &&
      publishedAccountRoster.projection ===
        accountRosterProjection(observedPeers!);
