//! Verified historical device/account proofs, without IP addresses or endpoint freshness.
use crate::identity::account_transition::AccountBindingTransition;
use crate::storage::encryption::{
    EncryptionKey, NONCE_SIZE, SALT_SIZE, decrypt_data, encrypt_data, generate_salt,
};
use crate::{discovery::Announce, identity::device::PublicIdentity};
use bincode::Options;
use serde::{Deserialize, Serialize};
use std::{
    fs::{self, File},
    io::{self, Read, Write},
    path::{Path, PathBuf},
};

const MAGIC: &[u8; 6] = b"MTPDR1";
const MAX_BYTES: u64 = 1_048_576;
const MAX_PEERS: usize = 1024;
const HEADER: usize = MAGIC.len() + SALT_SIZE + NONCE_SIZE;
fn invalid() -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, "invalid peer directory")
}
fn invalid_error(_: impl std::fmt::Display) -> io::Error {
    invalid()
}
#[derive(Debug)]
enum RecordRejection {
    InvalidPresence,
    LinkedBindingConflict,
    DeviceKeyConflict,
    AccountRootChange,
    DirectoryCapacity,
}
impl RecordRejection {
    fn code(&self) -> &'static str {
        match self {
            Self::InvalidPresence => "invalid_presence",
            Self::LinkedBindingConflict => "linked_binding_conflict",
            Self::DeviceKeyConflict => "device_key_conflict",
            Self::AccountRootChange => "account_root_change",
            Self::DirectoryCapacity => "directory_capacity",
        }
    }
    fn error(self) -> io::Error {
        io::Error::new(io::ErrorKind::InvalidData, self)
    }
}
impl std::fmt::Display for RecordRejection {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("invalid peer directory")
    }
}
impl std::error::Error for RecordRejection {}

/// Content-free diagnostic for the existing passive proof rejection boundary.
pub(super) fn rejection_code(error: &io::Error) -> &'static str {
    error
        .get_ref()
        .and_then(|source| source.downcast_ref::<RecordRejection>())
        .map_or("invalid_data", RecordRejection::code)
}
fn codec() -> impl Options {
    bincode::DefaultOptions::new()
        .with_fixint_encoding()
        .with_limit(MAX_BYTES)
        .reject_trailing_bytes()
}
fn check_path(path: &Path) -> io::Result<bool> {
    match fs::symlink_metadata(path) {
        Ok(m) if m.is_file() => Ok(true),
        Ok(_) => Err(invalid()),
        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(false),
        Err(e) => Err(e),
    }
}
fn valid(announce: &Announce) -> bool {
    announce.valid_presence() && announce.account_cert.is_some()
}
#[derive(Serialize, Deserialize)]
struct Snapshot {
    version: u32,
    records: Vec<Announce>,
}

#[derive(Clone, Serialize, Deserialize)]
struct TransitionHead {
    public: PublicIdentity,
    id: [u8; 32],
    transitions: Vec<AccountBindingTransition>,
}
#[derive(Clone, Serialize, Deserialize)]
pub(super) struct AccountBindingPatch {
    pub(super) announce: Announce,
    pub(super) transitions: Vec<AccountBindingTransition>,
}
#[derive(Serialize, Deserialize)]
struct SnapshotV2 {
    version: u32,
    records: Vec<Announce>,
    heads: Vec<TransitionHead>,
}

#[derive(Serialize, Deserialize)]
struct SnapshotV3 {
    version: u32,
    records: Vec<Announce>,
    heads: Vec<TransitionHead>,
    // Conservative query evidence only; never a current identity/authority grant.
    ambiguous_accounts: Vec<PublicIdentity>,
}

/// One serialized owner per file, in a trusted parent directory, as with PrivacyPolicy.
/// Records establish historical author/account bindings, never a fresh dial endpoint.
/// Existing symlinks are rejected; filesystem races in an untrusted parent are out of scope.
pub(crate) struct PeerDirectory {
    path: PathBuf,
    salt: [u8; SALT_SIZE],
    key: EncryptionKey,
    records: Vec<Announce>,
    heads: Vec<TransitionHead>,
    revision: u64,
    ambiguous_accounts: Vec<PublicIdentity>,
    // Reconstructed from the durable local account-device registry at startup.
    linked_bindings: Vec<super::account_devices::AccountDevice>,
}
impl PeerDirectory {
    pub(crate) fn open(path: &Path, password: &str) -> io::Result<Self> {
        if !check_path(path)? {
            let salt = generate_salt();
            let directory = Self {
                path: path.into(),
                salt,
                key: EncryptionKey::from_password(password, &salt).map_err(invalid_error)?,
                records: Vec::new(),
                heads: Vec::new(),
                revision: 0,
                ambiguous_accounts: Vec::new(),
                linked_bindings: Vec::new(),
            };
            directory.save(&[])?;
            return Ok(directory);
        }
        let file = File::open(path)?;
        if !file.metadata()?.is_file() {
            return Err(invalid());
        }
        let mut bytes = Vec::new();
        file.take(MAX_BYTES + 1).read_to_end(&mut bytes)?;
        if bytes.len() < HEADER + 16
            || bytes.len() as u64 > MAX_BYTES
            || &bytes[..MAGIC.len()] != MAGIC
        {
            return Err(invalid());
        }
        let salt = bytes[MAGIC.len()..MAGIC.len() + SALT_SIZE]
            .try_into()
            .map_err(invalid_error)?;
        let nonce = bytes[MAGIC.len() + SALT_SIZE..HEADER]
            .try_into()
            .map_err(invalid_error)?;
        let key = EncryptionKey::from_password(password, &salt).map_err(invalid_error)?;
        let plaintext = decrypt_data(&bytes[HEADER..], &nonce, &key).map_err(invalid_error)?;
        let (snapshot, heads, mut ambiguous_accounts) = match plaintext.get(..4) {
            Some([1, 0, 0, 0]) => {
                let snapshot: Snapshot = codec().deserialize(&plaintext).map_err(invalid_error)?;
                (snapshot, Vec::new(), Vec::new())
            }
            Some([2, 0, 0, 0]) => {
                let snapshot: SnapshotV2 =
                    codec().deserialize(&plaintext).map_err(invalid_error)?;
                (
                    Snapshot {
                        version: 1,
                        records: snapshot.records,
                    },
                    snapshot.heads,
                    Vec::new(),
                )
            }
            Some([3, 0, 0, 0]) => {
                let snapshot: SnapshotV3 =
                    codec().deserialize(&plaintext).map_err(invalid_error)?;
                (
                    Snapshot {
                        version: 1,
                        records: snapshot.records,
                    },
                    snapshot.heads,
                    snapshot.ambiguous_accounts,
                )
            }
            _ => return Err(invalid()),
        };
        if heads.len() > MAX_PEERS
            || heads
                .windows(2)
                .any(|w| w[0].public.user_id() >= w[1].public.user_id())
            || heads.iter().any(|h| {
                h.transitions.is_empty()
                    || h.transitions.len() > 8
                    || h.transitions
                        .first()
                        .is_some_and(|t| t.previous_transition.is_some())
                    || h.transitions.last().is_none_or(|t| t.id() != h.id)
                    || h.transitions
                        .iter()
                        .any(|t| t.public != h.public || !t.verify())
                    || h.transitions.windows(2).any(|w| {
                        w[1].previous_transition != Some(w[0].id())
                            || w[1].previous_certificate != w[0].current_certificate
                    })
                    || !snapshot.records.iter().any(|r| r.public() == h.public)
            })
        {
            return Err(invalid());
        }
        if ambiguous_accounts.len() > MAX_PEERS
            || ambiguous_accounts
                .windows(2)
                .any(|pair| pair[0].user_id() >= pair[1].user_id())
            || ambiguous_accounts.iter().any(|public| {
                !snapshot
                    .records
                    .iter()
                    .any(|record| record.public() == *public)
            })
        {
            return Err(invalid());
        }
        // Pre-V3 formats could erase previous roots during explicit acceptance.
        // Their latest certificate alone cannot establish an old event's account.
        // Keep current identity/admission records; only historical attribution is
        // conservative until immutable event-bound or causal proof is available.
        if matches!(plaintext.get(..4), Some([1, 0, 0, 0] | [2, 0, 0, 0])) {
            ambiguous_accounts = snapshot.records.iter().map(Announce::public).collect();
        }
        // V2 chains already prove a historical root change. Preserve that fact
        // independently when an explicit acceptance later replaces its head.
        for head in &heads {
            if !ambiguous_accounts.contains(&head.public) {
                ambiguous_accounts.push(head.public.clone());
            }
        }
        ambiguous_accounts.sort_by_key(PublicIdentity::user_id);
        if snapshot.version != 1 || snapshot.records.len() > MAX_PEERS {
            return Err(invalid());
        Ok(
            self.account_allowed(peer.public_identity(), peer.announcement())
                || self.group_member(peer.public_identity())?
                || self.group_departure_peer(peer.public_identity()),
        )
    }
    // This bit describes disclosure on this connection. Physical-LAN-only
    // peers stay visible to their actual LAN neighbors while overlay contacts
    // receive private presence. Use the connected endpoint, including IPv6 scope.
    fn publicly_visible_at(&self, endpoint: std::net::SocketAddr) -> bool {
        if self.privacy_snapshot().invisible {
            return false;
        }
        if !self.physical_lan_only() {
            return true;
        }
        self.privacy
            .state
            .read()
            .expect("privacy lock not poisoned")
            .as_ref()
            .is_some_and(|state| state.visibility.accepts_source(endpoint))
    }

    fn own_presence(&self) -> Option<Announce> {
        self.privacy
            .state
            .read()
            .expect("privacy lock not poisoned")
            .as_ref()
            .map(|s| s.own.clone())
    }
    #[cfg(test)]
    pub(in crate::node) fn remember_peer(
        &self,
        public: &PublicIdentity,
        announce: Option<&Announce>,
        ip: std::net::IpAddr,
    ) -> Result<(), TransportError> {
        self.remember_peer_with_visibility(public, announce, ip, true)
    }

    pub(in crate::node) fn remember_peer_with_visibility(
        &self,
        public: &PublicIdentity,
        announce: Option<&Announce>,
        ip: std::net::IpAddr,
        publicly_visible: bool,
    ) -> Result<(), TransportError> {
        let ip = crate::transport::net::canonical_peer_ip(ip);
        let Some(announce) = announce else {
            return Ok(());
        };
        if announce.public() != *public || !announce.verify() {
            return Err(TransportError::IdentityMismatch);
        }
        let direct_route_allowed = |state: &PrivacyState| {
            !state.policy.snapshot().invisible
                || announce.account_id().is_some_and(|account| {
                    account == self.account_id() || state.policy.allows(&account)
                })
        };
        let group_allowed = || {
            self.group_member(public)
                .map(|member| member || self.group_departure_peer(public))
                .map_err(|error| TransportError::Io(io::Error::other(error)))
        };
        let needs_group = {
            let guard = self
                .privacy
                .state
                .read()
                .expect("privacy lock not poisoned");
            guard
                .as_ref()
                .is_some_and(|state| !direct_route_allowed(state))
        };
        let mut group_member = if needs_group {
            Some(group_allowed()?)
        } else {
            None
        };
        #[cfg(test)]
        if let Some(hook) = self.remember_peer_hook.lock().unwrap().take() {
            hook();
        }
        // Declared before the policy/roster guards: even a later route-write
        // failure wakes retry work only after those guards have retired.
        let mut proof_wake = ProfileFactWake {
            changed: false,
            wake: Some(self.storage.database().maintenance_waker()),
        };
        loop {
            let mut guard = self
                .privacy
                .state
                .write()
                .expect("privacy lock not poisoned");
            let Some(state) = guard.as_mut() else {
                break;
            };
            let direct = direct_route_allowed(state);
            if !direct && group_member.is_none() {
                // Policy may have tightened since the read above. Query current
                // membership without the privacy guard, then recheck the owner.
                drop(guard);
                group_member = Some(group_allowed()?);
                continue;
            }
            if announce.account_id().is_some() {
                let revision = state.proofs.revision();
                state
                    .proofs
                    .record(announce)
