                let channel = metadata.conversation;
                if !self
                    .log
                    .lock()
                    .expect("log mutex")
                    .repository()?
                    .has_kind(&channel, EventKind::MembershipChange)?
                {
                    continue;
                }
                loop {
                    let ready = {
                        let log = self.log.lock().expect("log mutex");
                        let repository = log.repository()?;
