const MAX_UNKNOWN_DEVICES = 256;

/** An unmapped device is a scheduling hint, never an account identity. */
export function createUnknownContactRefresh(refresh: () => Promise<void>) {
  const devices = new Map<string, { next: number; pending: boolean }>();
  let due = Infinity;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let armed = Infinity;
  let active: Promise<void> | undefined;

  function disarm() {
    if (timer !== undefined) clearTimeout(timer);
    timer = undefined;
    armed = Infinity;
  }

  function schedule() {
    // Let the current read publish. Its completion drains hints received after
    // it started, including when a native read outlasts the two-second window.
    if (active || due === armed) return;
    disarm();
    armed = due;
    timer = setTimeout(run, Math.max(0, due - performance.now()));
  }

  function run() {
    disarm();
    due = Infinity;
    const next = performance.now() + UNKNOWN_SENDER_REPAIR_MS;
    // One whole account-list read covers all hints received before this call.
    for (const entry of devices.values()) {
      if (entry.pending) {
        entry.next = next;
        entry.pending = false;
      }
    }
    const read = refresh();
    if (active === read) return;
    active = read;
    void read.finally(() => {
      if (active !== read) return;
      active = undefined;
      schedule();
    });
  }

  return {
    observe(device: string) {
      const now = performance.now();
      const entry = devices.get(device);
      if (!active && !entry && devices.size === MAX_UNKNOWN_DEVICES) {
        for (const [id, observed] of devices) {
          if (!observed.pending && observed.next <= now) devices.delete(id);
        }
      }
      if (
        entry
          ? !active && entry.next <= now
          : devices.size < MAX_UNKNOWN_DEVICES
      ) {
        devices.set(device, {
          next: now + UNKNOWN_SENDER_REPAIR_MS,
          pending: false,
        });
        run();
        return;
      }
      // Excess device IDs share a single trailing request without allocating
      // more keys. Repeated hints cannot postpone an existing deadline.
      if (entry) entry.pending = true;
      due = Math.min(due, entry?.next ?? now + UNKNOWN_SENDER_REPAIR_MS);
      schedule();
    },
    reset() {
      disarm();
      due = Infinity;
      active = undefined;
      devices.clear();
    },
  };
}

